  if(action==='guide-preparation'){const o=occupationById(state.guide.primaryCareer),routes=o?.finance?.educationRoutes.routes||o?.preparation.typicalEducation||[];if(!routes.includes(el.dataset.value))return;state.guide.preparation=el.dataset.value;if(state.guide.salaryPicked){createPlanActions(state);persist();go('plan');}else{persist();go('guide/income');}return;}
